import AvatarFallback from './AvatarFallback.vue'
import AvatarGroup from './AvatarGroup.vue'
import AvatarImage from './AvatarImage.vue'
import AvatarRoot from './AvatarRoot.vue'

export const Avatar = {
  /**
   * AvatarGroup component
   *
   * Wraps multiple Avatar components to display them as a group with overlapping
   * styles.
   */
  Group: AvatarGroup,

  /** AvatarRoot component */
  Root: AvatarRoot,

  /** AvatarImage component */
  Image: AvatarImage,

  /** AvatarFallback component */
  Fallback: AvatarFallback,
}

import { cva } from 'class-variance-authority'

export const shape = {
  round: 'rounded-full',
  square: 'rounded-sm',
}

export const size = {
  sm: 'size-8 text-xs',
  md: 'size-10 text-sm',
  lg: 'size-12 text-base',
  xl: 'size-14 text-lg',
}

export const avatarVariants = cva(
  'relative flex shrink-0 overflow-hidden',
  {
    variants: { shape, size },
    defaultVariants: { shape: 'round', size: 'md' },
  },
)

import type { ClassValue } from 'clsx'

import { clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import { createContext } from '@/composables/createContext'

import type { size } from './variant'

export const [provideAvatarContext, useAvatarContext] = createContext<{
  shape: 'round' | 'square'
  size: keyof typeof size
}>('Avatar')
